 rows.append({'instruction':n,'entry':ref('lib.rs','pub fn '+n),'context':ref(*context) if context else None,'body':ref(*body)if body else ref('lib.rs','pub fn '+n),'authorization_and_accounts':admission,'effects_and_failure_order':effects,'unresolved_or_applicability':limits})
